values ('bbbb0001-0000-4000-8000-000000000008', 'en', null, 'Trigonometry', 'A guided first course in trigonometry — from angles and radian measure to the unit circle, the graphs of sine and cosine, identities, and solving any triangle. Structure adapted from OpenStax Algebra and Trigonometry 2e (CC BY 4.0).', null, 'foundations', 8, true, 'math', '{bbbb0001-0000-4000-8000-000000000004}')
