insert into public.lessons (course_id, position, title, kind, body, grammar_notes_md, estimated_minutes)
select 'bbbb0001-0000-4000-8000-000000000008', v.pos, v.title, v.kind, v.body::jsonb, v.notes, v.mins
from (values
  (1, 'Diagnostic: where are you now?', 'quiz', '{"questions":[{"prompt":"How many radians equal 180 degrees?","options":["pi/2","pi","2pi","pi/4"],"answer":1,"explanation":"A straight angle is half a full turn, and a full turn is 2pi radians, so 180 degrees = pi radians."},{"prompt":"In SOHCAHTOA, the sine of an acute angle in a right triangle equals…","options":["adjacent / hypotenuse","opposite / hypotenuse","opposite / adjacent","hypotenuse / opposite"],"answer":1,"explanation":"SOH: Sine = Opposite / Hypotenuse."},{"prompt":"On the unit circle, the point at angle theta has coordinates…","options":["(sin theta, cos theta)","(cos theta, sin theta)","(tan theta, 1)","(cos theta, tan theta)"],"answer":1,"explanation":"The x-coordinate is cos theta and the y-coordinate is sin theta."},{"prompt":"What is sin(30 degrees)?","options":["1/2","sqrt(3)/2","sqrt(2)/2","1"],"answer":0,"explanation":"sin(30 degrees) = 1/2 is a standard special-angle value."},{"prompt":"The period of y = sin(x) is…","options":["pi","pi/2","2pi","1"],"answer":2,"explanation":"Sine repeats every full turn, so its period is 2pi."},{"prompt":"For every angle, sin^2(x) + cos^2(x) equals…","options":["0","1","2","tan(x)"],"answer":1,"explanation":"This is the Pythagorean identity: sin^2 + cos^2 = 1."},{"prompt":"The Law of Sines says that in any triangle…","options":["a^2 + b^2 = c^2","a/sin(A) = b/sin(B) = c/sin(C)","a + b = c","sin(A) = a/b"],"answer":1,"explanation":"Each side over the sine of its opposite angle gives the same ratio."},{"prompt":"Which is a correct definition of the tangent function?","options":["tan(x) = cos(x)/sin(x)","tan(x) = sin(x)/cos(x)","tan(x) = 1/sin(x)","tan(x) = sin(x)*cos(x)"],"answer":1,"explanation":"Tangent is sine divided by cosine."}]}'::jsonb, null, 10),
  (2, 'Angles and radian measure', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Measure angles in both degrees and radians, convert between them, and find arc length. Warm-up: if a full turn is 360 degrees, and also 2pi radians, what single angle is both 90 degrees and pi/2 radians?"},{"heading":"The idea","text":"An angle can be measured in degrees (a full turn is 360 degrees) or in radians. One radian is the angle that wraps an arc equal to the radius around a circle. Since the whole circumference is 2pi radii, a full turn is 2pi radians. That gives the master link: 180 degrees = pi radians. To go from degrees to radians, multiply by pi/180; to go back, multiply by 180/pi. Arc length uses radians directly: s = r * theta."},{"heading":"Worked examples","text":"Convert 60 degrees to radians: 60 * pi/180 = pi/3. Convert 3pi/4 radians to degrees: (3pi/4) * 180/pi = 135 degrees. Arc length: a circle of radius r = 3 swept through theta = pi/2 gives s = 3 * (pi/2) = 3pi/2, about 4.71 units. Check the common special angles: 30 degrees = pi/6, 45 degrees = pi/4, 60 degrees = pi/3, 90 degrees = pi/2."},{"heading":"Your turn","text":"Convert each (answers follow). (1) 45 degrees to radians. (2) 120 degrees to radians. (3) pi/6 radians to degrees. (4) 2pi radians to degrees. (5) Arc length for r = 5, theta = pi/3. Answers: (1) pi/4; (2) 2pi/3; (3) 30 degrees; (4) 360 degrees; (5) s = 5 * pi/3 = 5pi/3, about 5.24 units."},{"heading":"Common mistakes & exit ticket","text":"Mistake: using degrees in s = r*theta — the formula needs radians. Mistake: thinking pi radians is a full circle (it is a half turn, 180 degrees). Exit: (a) 90 degrees is how many radians? (b) What must theta be measured in for s = r*theta? Answers: (a) pi/2; (b) radians."}]}'::jsonb, 'Degrees to radians: multiply by pi/180. Radians to degrees: multiply by 180/pi.', 12),
  (3, 'Right-triangle trig: SOHCAHTOA', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Use SOHCAHTOA to find a side or an angle in a right triangle. Warm-up: in a right triangle, which side is always the longest, and which angle does it sit opposite?"},{"heading":"The idea","text":"In a right triangle, pick one acute angle. The side across from it is the opposite, the side touching it (that is not the hypotenuse) is the adjacent, and the longest side across from the right angle is the hypotenuse. Then: sin = opposite/hypotenuse, cos = adjacent/hypotenuse, tan = opposite/adjacent. The mnemonic SOH-CAH-TOA packs all three. Because the opposite and adjacent swap when you switch angles, always name your angle first."},{"heading":"Worked examples","text":"Take the classic 3-4-5 right triangle with legs 3 and 4 and hypotenuse 5. For the angle opposite the side of length 3: sin = 3/5 = 0.6, cos = 4/5 = 0.8, tan = 3/4 = 0.75. Notice sin^2 + cos^2 = (3/5)^2 + (4/5)^2 = 9/25 + 16/25 = 1, exactly as the Pythagorean identity predicts. Finding a side: if an angle is 30 degrees and its hypotenuse is 10, the opposite side is 10 * sin(30 degrees) = 10 * (1/2) = 5."},{"heading":"Your turn","text":"Use the 3-4-5 triangle and the special angles (answers follow). (1) For the angle opposite the side 4, what is sin? (2) …what is tan? (3) tan(45 degrees) = ? (4) A hypotenuse of 8 at angle 60 degrees: length of the opposite side? (5) cos(60 degrees) = ? Answers: (1) 4/5 = 0.8; (2) 4/3, about 1.33; (3) 1; (4) 8 * sin(60 degrees) = 8 * sqrt(3)/2 = 4*sqrt(3), about 6.93; (5) 1/2."},{"heading":"Common mistakes & exit ticket","text":"Mistake: keeping the same ''opposite'' after you switch to the other acute angle — opposite and adjacent trade places. Mistake: using tan when you know the hypotenuse (tan ignores the hypotenuse). Exit: (a) Which ratio uses only the two legs? (b) In the 3-4-5 triangle, cos of the angle opposite side 3 is? Answers: (a) tangent; (b) 4/5."}]}'::jsonb, 'SOH-CAH-TOA: Sine=Opp/Hyp, Cosine=Adj/Hyp, Tangent=Opp/Adj — always relative to the chosen angle.', 12),
  (4, 'The unit circle and the six functions', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Read sine and cosine off the unit circle and define all six trig functions. Warm-up: on a circle of radius 1, what are the coordinates of the point straight to the right, at angle 0?"},{"heading":"The idea","text":"The unit circle has radius 1 and is centered at the origin. For an angle theta measured counterclockwise from the positive x-axis, the point where the terminal side meets the circle is exactly (cos theta, sin theta). This extends sine and cosine to every angle, not just acute ones. The other four functions are ratios of these two: tan = sin/cos, cot = cos/sin, sec = 1/cos, csc = 1/sin. Signs follow the quadrant: cosine is the x-coordinate, sine is the y-coordinate."},{"heading":"Worked examples","text":"Quadrantal points: at 0 the point is (1, 0), so cos(0) = 1, sin(0) = 0. At pi/2 (90 degrees) it is (0, 1), so cos = 0, sin = 1. At pi (180 degrees) it is (-1, 0). At 3pi/2 (270 degrees) it is (0, -1). A special angle: at pi/3 (60 degrees) the point is (cos(60 degrees), sin(60 degrees)) = (1/2, sqrt(3)/2), about (0.5, 0.866). Then tan(60 degrees) = sin/cos = (sqrt(3)/2)/(1/2) = sqrt(3), about 1.73, and sec(60 degrees) = 1/cos = 1/(1/2) = 2."},{"heading":"Your turn","text":"Use the unit circle (answers follow). (1) sin(pi/2) = ? (2) cos(pi) = ? (3) At 45 degrees the point is (sqrt(2)/2, sqrt(2)/2); what is tan(45 degrees)? (4) csc(pi/2) = ? (5) Which function equals the x-coordinate of the point? (6) cos(3pi/2) = ? Answers: (1) 1; (2) -1; (3) (sqrt(2)/2)/(sqrt(2)/2) = 1; (4) 1/sin(pi/2) = 1; (5) cosine; (6) 0."},{"heading":"Common mistakes & exit ticket","text":"Mistake: swapping the coordinates and reading sine as the x-value (sine is y, the vertical one). Mistake: writing sec = 1/sin (it is 1/cos). Exit: (a) The y-coordinate on the unit circle is which function? (b) sec theta is the reciprocal of what? Answers: (a) sine; (b) cosine."}]}'::jsonb, 'On the unit circle, x = cos theta and y = sin theta; the other four functions are built from these two.', 13),
  (5, 'Checkpoint 1', 'quiz', '{"questions":[{"prompt":"Convert 90 degrees to radians.","options":["pi","pi/2","pi/3","2pi"],"answer":1,"explanation":"90 * pi/180 = pi/2."},{"prompt":"Arc length for a circle of radius 4 swept through theta = pi/2 is…","options":["2pi","4pi","pi/2","8"],"answer":0,"explanation":"s = r*theta = 4 * (pi/2) = 2pi."},{"prompt":"In the 3-4-5 right triangle, the tangent of the angle opposite the side of length 3 is…","options":["3/5","4/5","3/4","5/4"],"answer":2,"explanation":"tan = opposite/adjacent = 3/4."},{"prompt":"What are the coordinates of the unit-circle point at angle pi (180 degrees)?","options":["(0, 1)","(1, 0)","(-1, 0)","(0, -1)"],"answer":2,"explanation":"At pi the point is (cos pi, sin pi) = (-1, 0)."},{"prompt":"cos(60 degrees) equals…","options":["1/2","sqrt(3)/2","sqrt(2)/2","1"],"answer":0,"explanation":"cos(60 degrees) = 1/2 is a standard special-angle value."},{"prompt":"Which expression equals sec(theta)?","options":["1/sin(theta)","1/cos(theta)","sin/cos","cos/sin"],"answer":1,"explanation":"Secant is the reciprocal of cosine."}]}'::jsonb, null, 8),
  (6, 'Graphs of sine and cosine', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Sketch y = sin(x) and y = cos(x) and read off amplitude and period. Warm-up: as the unit-circle point goes around once, its height (the y-value) rises and falls — how many times does it return to the same height in one full turn?"},{"heading":"The idea","text":"Plotting the unit-circle height against the angle traces the sine wave; plotting the x-coordinate traces the cosine wave. Both are smooth waves with amplitude 1 (they run from -1 to 1) and period 2pi (one full turn). The difference is the starting point: sin(0) = 0 rises to a peak at pi/2, while cos(0) = 1 starts at its peak. For a scaled wave y = A*sin(Bx), the amplitude is |A| (the height of the peak) and the period is 2pi/B (how far along x before it repeats)."},{"heading":"Worked examples","text":"Key points of y = sin(x) over one period: sin(0) = 0, sin(pi/2) = 1 (peak), sin(pi) = 0, sin(3pi/2) = -1 (trough), sin(2pi) = 0. For y = cos(x): cos(0) = 1 (peak), cos(pi/2) = 0, cos(pi) = -1 (trough), cos(3pi/2) = 0, cos(2pi) = 1. Scaling: y = 3*sin(2x) has amplitude |3| = 3 and period 2pi/2 = pi, so it makes two full waves between 0 and 2pi and reaches up to 3 and down to -3."},{"heading":"Your turn","text":"Answer from the graphs (answers follow). (1) Amplitude of y = 5*cos(x)? (2) Period of y = sin(3x)? (3) At what x in [0, 2pi] does sin(x) first reach its peak? (4) What is the value of cos(x) at x = pi? (5) Does y = cos(x) start at 0 or at 1? (6) Period of y = 2*sin(x)? Answers: (1) 5; (2) 2pi/3; (3) pi/2; (4) -1; (5) at 1; (6) 2pi."},{"heading":"Common mistakes & exit ticket","text":"Mistake: thinking B changes the amplitude — B changes the period (2pi/B), while A sets the amplitude. Mistake: starting the cosine graph at 0 like sine (cosine starts at its peak, 1). Exit: (a) What is the period of y = sin(4x)? (b) Which graph starts at its maximum, sine or cosine? Answers: (a) 2pi/4 = pi/2; (b) cosine."}]}'::jsonb, 'For y = A*sin(Bx): amplitude = |A|, period = 2pi/B. Cosine starts at a peak; sine starts at zero.', 13),
  (7, 'Solving any triangle: laws of sines and cosines', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Solve triangles that are not right triangles using the Law of Sines and the Law of Cosines. Warm-up: SOHCAHTOA needs a right angle — what do you do when a triangle has no 90-degree corner?"},{"heading":"The idea","text":"For any triangle, label each side with the lowercase letter of the angle across from it: side a is opposite angle A, and so on. The Law of Sines says a/sin(A) = b/sin(B) = c/sin(C); use it when you know an angle and its opposite side plus one more piece (AAS, ASA, or the SSA case). The Law of Cosines, c^2 = a^2 + b^2 - 2ab*cos(C), is the general form of the Pythagorean theorem; use it when you know two sides and the angle between them (SAS) or all three sides (SSS). When C = 90 degrees, cos(C) = 0 and the Law of Cosines collapses to c^2 = a^2 + b^2."},{"heading":"Worked examples","text":"Law of Sines: given A = 30 degrees, a = 5, and B = 45 degrees, find b. Then b = a*sin(B)/sin(A) = 5 * sin(45 degrees)/sin(30 degrees) = 5 * (sqrt(2)/2)/(1/2) = 5 * sqrt(2), about 7.07. Law of Cosines: given sides a = 5 and b = 7 with the included angle C = 60 degrees, find c. Then c^2 = 5^2 + 7^2 - 2*5*7*cos(60 degrees) = 25 + 49 - 70*(1/2) = 74 - 35 = 39, so c = sqrt(39), about 6.24."},{"heading":"Your turn","text":"Solve (answers follow). (1) In the Law of Sines, side a sits opposite which angle? (2) Which law fits SAS (two sides and the included angle)? (3) With a = 8, A = 90 degrees, B = 30 degrees, find b using b = a*sin(B)/sin(A). (4) Law of Cosines with a = 3, b = 4, C = 90 degrees: find c. (5) What does cos(C) become when C = 90 degrees? Answers: (1) angle A; (2) Law of Cosines; (3) 8 * sin(30 degrees)/sin(90 degrees) = 8 * (1/2)/1 = 4; (4) c^2 = 9 + 16 - 0 = 25, so c = 5; (5) 0."},{"heading":"Common mistakes & exit ticket","text":"Mistake: pairing a side with the wrong angle in the Law of Sines — each side goes with the angle across from it, not next to it. Mistake: dropping the minus sign or the factor 2 in 2ab*cos(C). Exit: (a) Which law needs two sides and the angle between them? (b) When the included angle is 90 degrees, the Law of Cosines becomes which famous theorem? Answers: (a) Law of Cosines; (b) the Pythagorean theorem."}]}'::jsonb, 'Law of Sines: a/sin(A) = b/sin(B) = c/sin(C). Law of Cosines: c^2 = a^2 + b^2 - 2ab*cos(C).', 14),
  (8, 'Key terms', 'vocab', '{"items":[{"term":"radian","translation":"an angle measure where a full turn is 2pi and 180 degrees = pi radians","example":"Converting 90 degrees gives 90 * pi/180 = pi/2 radians."},{"term":"hypotenuse","translation":"the longest side of a right triangle, opposite the right angle","example":"In a 3-4-5 triangle the hypotenuse is 5."},{"term":"sine","translation":"opposite over hypotenuse; the y-coordinate of the unit-circle point","example":"sin(30 degrees) = 1/2."},{"term":"unit circle","translation":"the circle of radius 1 centered at the origin, where a point at angle theta is (cos theta, sin theta)","example":"At pi/2 the unit-circle point is (0, 1)."},{"term":"period","translation":"the horizontal length of one full cycle of a periodic graph","example":"The period of y = sin(x) is 2pi."},{"term":"Law of Cosines","translation":"c^2 = a^2 + b^2 - 2ab*cos(C), the general form of the Pythagorean theorem","example":"With a = 5, b = 7, C = 60 degrees, c^2 = 74 - 35 = 39."}]}'::jsonb, null, 8),
  (9, 'Checkpoint 2', 'quiz', '{"questions":[{"prompt":"The amplitude of y = 5*cos(x) is…","options":["1","5","2pi","pi/5"],"answer":1,"explanation":"For y = A*cos(Bx), the amplitude is |A| = 5."},{"prompt":"The period of y = sin(3x) is…","options":["2pi","3pi","2pi/3","6pi"],"answer":2,"explanation":"Period = 2pi/B = 2pi/3."},{"prompt":"Which graph starts at its maximum value when x = 0?","options":["y = sin(x)","y = cos(x)","y = tan(x)","neither"],"answer":1,"explanation":"cos(0) = 1, its peak; sin(0) = 0."},{"prompt":"Which law solves a triangle given two sides and the angle between them (SAS)?","options":["Law of Sines","Law of Cosines","Pythagorean identity","SOHCAHTOA"],"answer":1,"explanation":"SAS needs the Law of Cosines: c^2 = a^2 + b^2 - 2ab*cos(C)."},{"prompt":"Using the Law of Sines with A = 30 degrees, a = 5, B = 45 degrees, side b equals…","options":["5*sqrt(2)","5/2","10","sqrt(5)"],"answer":0,"explanation":"b = 5*sin(45 degrees)/sin(30 degrees) = 5*(sqrt(2)/2)/(1/2) = 5*sqrt(2)."},{"prompt":"With a = 5, b = 7 and included angle C = 60 degrees, the Law of Cosines gives c^2 =","options":["74","39","35","24"],"answer":1,"explanation":"c^2 = 25 + 49 - 2*5*7*(1/2) = 74 - 35 = 39."}]}'::jsonb, null, 8),
  (10, 'Applied project: measure something you can''t reach', 'writing', '{"sections":[{"heading":"The task","text":"Plan how to find a distance or height you cannot measure directly — the height of a tree, the width of a river, or the distance to a building — using only angles and one measurable baseline. You will not need special equipment; you will design the calculation rigorously."},{"heading":"Milestones","text":"1) Sketch the situation as a triangle and label which sides and angles you could actually measure from the ground. 2) Decide whether your known pieces fit a right-triangle SOHCAHTOA setup, the Law of Sines, or the Law of Cosines, and say why. 3) Write the exact equation you would solve, with your chosen angle in either degrees or radians stated clearly. 4) Carry out the arithmetic with plausible sample numbers and report the result with units."},{"heading":"Self-check rubric","text":"Check that your triangle labels each side opposite its angle. Check that the law you chose matches the information you have (right angle -> SOHCAHTOA; an angle with its opposite side -> Law of Sines; two sides and the included angle -> Law of Cosines). Check that your equation is solvable and your units are consistent. Check that a sanity estimate (is the answer roughly the size you expected?) passes. If all four hold, you have solved a real triangle the way a surveyor would."}]}'::jsonb, null, 15)
) as v(pos, title, kind, body, notes, mins)
where not exists (
  select 1 from public.lessons l
  where l.course_id = 'bbbb0001-0000-4000-8000-000000000008' and l.position = v.pos
);
